def transform(grid):
    g = np.array(grid)
    out = g.copy()
    h, w = g.shape
    for y in range(h):
        row = g[y]
        twos = [x for x in range(w) if row[x] == 2]
        changed = False
        for a, b in zip(twos, twos[1:]):
            if b - a <= 1:
                continue
            xs = range(a + 1, b)
            if not all(row[x] == 0 for x in xs):
                continue
            touches = any((y > 0 and g[y - 1, x] == 2) or (y < h - 1 and g[y + 1, x] == 2) for x in xs)
            if touches:
                continue
            out[y, a + 1:b] = 9
            changed = True
        if changed:
            emit(out, f"Row {y}: fill the 0-gap squeezed between two 2-blocks (no 2 above/below it) with 9.")
    emit(out, "Final grid: every horizontal channel between two 2-blocks is bridged with 9.")
    return out
